export const OS_QUESTIONS = [
  {q:"Which of the following are NOT shared by threads of the same process?",options:["Stack and Registers","Registers and Address space","Stack and Address space","Address space and Message queue"],ans:0,exp:"Each thread has its own stack and register set, but shares address space with other threads of the same process."},
  {q:"The problem of indefinite blockage of low priority jobs in priority scheduling can be solved using?",options:["Swapping","Dirty Bit","Aging","Compaction"],ans:2,exp:"Aging gradually increases the priority of waiting processes, preventing indefinite blockage (starvation)."},
  {q:"Which of the following are advantages of Multiprogramming?",options:["High and efficient CPU utilization","CPU scheduling is not required","Memory management is good","All of the above"],ans:0,exp:"Multiprogramming keeps the CPU busy by switching between processes, maximizing CPU utilization."},
  {q:"A memory management system has 64 pages with 512 bytes page size. Physical memory has 32 frames. Bits for logical and physical address are?",options:["14 and 15","14 and 29","15 and 14","16 and 32"],ans:2,exp:"Logical: log2(64×512)=log2(32768)=15 bits; Physical: log2(32×512)=log2(16384)=14 bits."},
  {q:"Consider reference string 0 1 2 3 0 1 4 0 1 2 3 4. Using FIFO with 3 frames and 4 frames, page faults are?",options:["10, 9","9, 9","10, 10","9, 10"],ans:3,exp:"With FIFO: 3 frames give 9 page faults and 4 frames give 10 — demonstrating Belady's anomaly."},
  {q:"Consider three CPU-intensive processes requiring 30, 20, 10 time units arriving at 0, 2, 6. Context switches with SRTF (excluding start and end)?",options:["1","2","3","4"],ans:1,exp:"SRTF preempts when a shorter job arrives. P2(20) preempts P1(28 remaining), and P3(10) preempts P2(16 remaining), causing 2 context switches."},
  {q:"Total disk head movement using SCAN for queue 6,10,12,54,97,73,128,15,44,110,34,45 starting at 23 moving toward 0?",options:["172","113","151","161"],ans:2,exp:"SCAN moves to 0 then reverses: 23→0 + 0→128 = 23+128=151 total head movements."},
  {q:"A counting semaphore starts at 10. After 12 P operations and x V operations, final value is 7. What is x?",options:["8","9","10","11"],ans:1,exp:"Semaphore: 10 - 12 + x = 7, so x = 9."},
  {q:"In which disk scheduling algorithm does the head move to one end then immediately return without servicing?",options:["LOOK","SCAN","C-SCAN","C-LOOK"],ans:2,exp:"C-SCAN (Circular SCAN) services requests in one direction, then returns to the beginning without servicing."},
  {q:"Paging suffers from which type of fragmentation?",options:["External","Internal","Physical","None of the mentioned"],ans:1,exp:"Paging eliminates external fragmentation but suffers from internal fragmentation within the last page frame."},
  {q:"In a multithreaded environment, which is used to avoid race conditions?",options:["Thread Pooling","Mutex","Paging","Deadlock"],ans:1,exp:"A mutex (mutual exclusion) lock ensures only one thread accesses a critical section at a time."},
  {q:"In a two-level directory structure, which is true?",options:["Files in different directories can have the same name","Files in same directory can have same name","Directories cannot have subdirectories","Each user can only have one file"],ans:0,exp:"Two-level directories allow different users to have files with the same name in their own directories."},
  {q:"A system is in deadlock state when?",options:["All processes are blocked","Processes are waiting for resources held by each other","CPU utilization is 0%","Processes are in ready state"],ans:1,exp:"Deadlock occurs when processes form a circular wait, each holding resources needed by the next."},
  {q:"A paging system with page size 4 KB. How many bits for offset in a 32-bit address?",options:["10 bits","12 bits","14 bits","15 bits"],ans:1,exp:"Page size = 4KB = 2^12 bytes, so 12 bits are needed for the offset within a page."},
  {q:"What is the primary purpose of an operating system?",options:["Enable direct hardware control","Manage system resources","Compile programs","Act as a debugger"],ans:1,exp:"The OS manages hardware resources (CPU, memory, I/O) and provides services to applications."},
  {q:"Which is an example of a process scheduling algorithm?",options:["Round Robin","Bubble sort","DFS","Quick sort"],ans:0,exp:"Round Robin is a CPU scheduling algorithm that assigns time slices to processes in circular order."},
  {q:"Which is NOT a primary function of an operating system?",options:["Memory management","Device management","File management","Database management"],ans:3,exp:"Database management is handled by DBMS software, not the operating system itself."},
  {q:"The Banker's algorithm grants resource requests if?",options:["Resources are immediately available","Resources don't exceed maximum claim","Resources don't exceed total available","All of the above"],ans:3,exp:"Banker's algorithm checks all three conditions before granting a request to ensure the system remains safe."},
  {q:"The Banker's algorithm is applicable to which type of resource allocation?",options:["Preemptive","Non-preemptive","Dynamic","Distributed"],ans:2,exp:"Banker's algorithm works with dynamic resource allocation, making decisions as requests arrive."},
  {q:"The Dining Philosophers problem can lead to deadlock if?",options:["All pick up left chopstick first","All pick up right chopstick first","All try to pick up both chopsticks","All are hungry at same time"],ans:0,exp:"If all philosophers pick up their left chopstick simultaneously, none can get the right one — deadlock."},
  {q:"Which memory management technique allocates memory in variable-sized blocks?",options:["Paging","Segmentation","Swapping","Fragmentation"],ans:1,exp:"Segmentation divides memory into variable-sized segments based on logical divisions of a program."},
  {q:"A deadlock in an operating system occurs when?",options:["A process cannot access a required resource indefinitely","A process gets stuck in infinite loop","A process exceeds memory limit","A process encounters an error"],ans:0,exp:"Deadlock occurs when a process is indefinitely blocked waiting for a resource held by another blocked process."},
  {q:"In a timesharing OS, when the time slot assigned to a process is completed, the process switches to?",options:["Suspended state","Terminated state","Ready state","Blocked state"],ans:2,exp:"When a time quantum expires, the process is preempted and moved back to the ready queue."},
  {q:"Dirty bit is used to indicate?",options:["A page fault has occurred","A page has corrupted data","A page has been modified after being loaded into cache","An illegal access of page"],ans:2,exp:"The dirty bit flags whether a page has been modified, determining if it needs to be written back to disk."},
  {q:"What is a short-term scheduler?",options:["Selects process for ready queue","Selects which process to execute next and allocates CPU","Selects process to remove from memory","None of the mentioned"],ans:1,exp:"The short-term (CPU) scheduler selects from ready processes and allocates the CPU to one of them."},
  {q:"If a process fails, most operating systems write error information to?",options:["New file","Another running process","Log file","None of the mentioned"],ans:2,exp:"Operating systems log error information to log files for debugging and system administration."},
  {q:"If a process is executing in its critical section, no other process can execute in their critical section. This condition is called?",options:["Mutual exclusion","Critical exclusion","Synchronous exclusion","Asynchronous exclusion"],ans:0,exp:"Mutual exclusion ensures that only one process can be in its critical section at any given time."},
  {q:"When are the register context and stack of a thread deallocated?",options:["When the thread terminates","When the thread blocks","When the thread unblocks","When the thread spawns"],ans:0,exp:"Thread resources like stack and register context are deallocated when the thread terminates."},
  {q:"Which page replacement algorithm suffers from Belady's anomaly?",options:["LRU","FIFO","Both LRU and FIFO","Optimal Page Replacement"],ans:1,exp:"FIFO can exhibit Belady's anomaly where more frames lead to more page faults."},
  {q:"Which of these is NOT shared by same process's threads?",options:["Address Space","Stack","Message Queue","File Descriptor Table"],ans:1,exp:"Each thread has its own private stack, while sharing address space, file descriptors, and message queues."},
  {q:"Which disk scheduling policy results in minimum head movement?",options:["Circular scan","SSTF","FCFS","None of the above"],ans:1,exp:"Shortest Seek Time First (SSTF) generally minimizes head movement by selecting the closest request next."},
  {q:"In a system with n CPUs, maximum processes in Ready State would be?",options:["Independent of n","2n","n²","n"],ans:0,exp:"The ready queue can hold any number of processes regardless of CPU count — it's limited by memory."},
  {q:"What is the CPU utilization if a system has 2 processes and each spends 50% of its time waiting for I/O?",options:["25%","50%","75%","100%"],ans:2,exp:"Probability both wait for I/O = 0.5² = 0.25. CPU utilization = 1 - 0.25 = 0.75 (75%)."},
  {q:"A system uses FIFO with 4 frames. First accesses 100 distinct pages then same 100 in reverse. Page faults?",options:["196","152","157","195"],ans:0,exp:"First pass: 100 faults (all new). Reverse pass: 96 faults (only last 4 pages cached). Total = 196."},
  {q:"What is a long-term scheduler?",options:["Selects processes for ready queue","Selects processes to execute next and allocates CPU","Selects processes to remove from memory by swapping","None of the mentioned"],ans:0,exp:"The long-term (job) scheduler selects which processes to admit into the system and load into memory."},
  {q:"A systematic procedure for moving the CPU to a new process is known as?",options:["Synchronization","Deadlock","Starvation","Context Switching"],ans:3,exp:"Context switching saves the state of the current process and loads the state of the next process to run."},
  {q:"In virtual memory:<br>• 32-bit virtual address<br>• 30-bit physical address<br>• 4KB pages<br>• 32-bit page table entry<br>Max bits for protection info?",options:["2","10","12","14"],ans:3,exp:"Physical frame bits = 30-12 = 18 bits. Page table entry = 32 bits. Protection bits = 32-18 = 14 bits."},
  {q:"The advantage of Round Robin CPU scheduling over Shortest Job First is?",options:["Better average turnaround time","Better average response time","Both (a) and (b)","Neither (a) nor (b)"],ans:1,exp:"Round Robin provides better response time by giving each process a fair time slice, though turnaround may be worse."},
  {q:"The first fit, best fit and worst fit are strategies to select?",options:["A process from queue to put in memory","A free hole from available holes","A processor to run next process","All of the above"],ans:1,exp:"These are memory allocation strategies for selecting a free memory hole to satisfy an allocation request."},
  {q:"For page size 200 words, the page number and offset for logical address 1142 are?",options:["5, 142","2, 142","6, 142","7, 140"],ans:0,exp:"Page number = 1142/200 = 5 (integer division), Offset = 1142 mod 200 = 142."},
  {q:"The advantage of Round Robin CPU scheduling over Shortest Job First scheduling is",options:["Better average turn around time","Better average response time","Both (a) and (b)","Neither (a) nor (b)"],ans:1,exp:"Round Robin ensures fair CPU time slices, dramatically improving response time for interactive processes over SJF."},
  {q:"The first fit, best fit and worst fit are strategies to select a",options:["process from a queue to put in memory","free hole from a set of available holes","processor to run the next process","all of the above"],ans:1,exp:"These are contiguous memory allocation algorithms used to select an appropriate free partition (hole) for a process."},
  {q:"For a page size of 200 words, what is the page number and offset for a logical address of 1142",options:["5,142","2,142","6,142","7,140"],ans:0,exp:"1142 / 200 = 5 (page number), and 1142 % 200 = 142 (offset)."},
  {q:"The process A, B, C, D and E references in the following order. A, B, C, D, A, B, E, A, B, C, D, E for the LRU page replacement algorithms with 4 frames. The number of page faults with pure demand paging is",options:["6","11","8","9"],ans:2,exp:"Tracking LRU gives exactly 8 page faults across the reference string."},
  {q:"A counting semaphore was initialized to 9. Then 27 P operations and 23 V operations were completed on this semaphore. The resulting value of the semaphore is",options:["0","5","7","13"],ans:1,exp:"P (wait) decreases by 1, V (signal) increases by 1. 9 - 27 + 23 = 5."},
  {q:"Suppose that a disk drive has 5000 tracks, numbered from 0 to 4999. The drive is currently serving a request at track 143 and the previous was at track 125. The queue of pending requests in FIFO order is 86,1470,913,1774,984, 1509, 1022,1750,130. Starting from the current position, the total distance in terms of track movement for SSTF is",options:["640","246","350","None"],ans:3,exp:"SSTF greedily chooses the closest track. The computed distance does not match the given options exactly."},
  {q:"External fragmentation exists when ....... ?",options:["Dynamic Programming","Primality algorithms","a request cannot be satisfied even when the total memory is free","enough total memory exists to satisfy a request but it is not contiguous"],ans:3,exp:"External fragmentation occurs when the total free memory is sufficient but is divided into small, non-contiguous blocks."},
  {q:"Consider the following three processes in the FCFS. P1(3,0), P2(6,9), P3(9,9). What is the average waiting time?",options:["2","3","4","6"],ans:0,exp:"P1 waits 0. P2 arrives at 9, starts at 9, waits 0. P3 arrives at 9, starts at 15, waits 6. Avg = (0+0+6)/3 = 2."},
  {q:"Which of the following algorithms is used to avoid deadlock?",options:["Dynamic Programming","Primality algorithm","Banker's algorithm","Deadlock algorithm"],ans:2,exp:"Banker's Algorithm simulates resource allocation to ensure the system remains in a safe state, avoiding deadlocks."},
  {q:"Which of the following component does not belong to PCB (Process Control Block)?",options:["CPU registers","CPU scheduling information","Accounting information","Operating System information"],ans:3,exp:"The PCB stores process-specific details. General 'Operating System information' is not kept in a PCB."}
];

